#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
APP_ROOT="$REPO_ROOT/life-circle-assistant"
REPORT_FILE="$APP_ROOT/docs/validation/reports/hongshan-haiyundonglu-20260921.json"
BENCHMARK_FILE="$APP_ROOT/docs/validation/benchmarks/hongshan-haiyundonglu-20260921.json"
REVIEW_GRID_FILE="$APP_ROOT/docs/validation/benchmarks/hongshan-haiyundonglu-20260921-review-grid.geojson"
RESULT_JSON="$APP_ROOT/docs/validation/results/hongshan-haiyundonglu-20260921.json"
RESULT_MD="$APP_ROOT/docs/validation/results/hongshan-haiyundonglu-20260921.md"

if [[ -x "$APP_ROOT/backend/.venv/bin/python" ]]; then
  PYTHON="$APP_ROOT/backend/.venv/bin/python"
elif command -v python3 >/dev/null 2>&1; then
  PYTHON="$(command -v python3)"
else
  printf '\n%s错误：未找到 Python 3，无法读写基准文件。%s\n' "$RED" "$RESET" >&2
  exit 1
fi

require_file() {
  if [[ ! -f "$1" ]]; then
    printf '\n%s错误：缺少文件 %s%s\n' "$RED" "$1" "$RESET" >&2
    exit 1
  fi
}

benchmark_default() {
  local field="$1"
  "$PYTHON" - "$BENCHMARK_FILE" "$field" <<'PY'
import json
import sys

path, field = sys.argv[1:]
data = json.load(open(path, encoding="utf-8"))
for label in data.get("labels", []):
    value = label.get("evidence", {}).get(field, "")
    if value:
        print(value)
        break
PY
}

prompt_required() {
  local variable="$1" prompt="$2" default_value="$3" input=""
  while true; do
    if [[ -n "$default_value" ]]; then
      printf '  %s%s%s %s[默认：%s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$default_value" "$RESET"
    else
      printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    fi
    read -r input || true
    [[ -z "$input" ]] && input="$default_value"
    if [[ -n "$input" ]]; then
      printf -v "$variable" '%s' "$input"
      return
    fi
    warn "该项不能为空。"
  done
}

save_review_defaults() {
  "$PYTHON" - "$BENCHMARK_FILE" "$REVIEWER" "$CHECKED_AT" "$EVIDENCE_SOURCE" <<'PY'
import json
import os
import sys
from pathlib import Path

path = Path(sys.argv[1])
reviewer, checked_at, source = sys.argv[2:]
data = json.loads(path.read_text(encoding="utf-8"))
updated = False
for label in data.get("labels", []):
    if label.get("expected_kind") is not None:
        continue
    evidence = label.setdefault("evidence", {})
    evidence["reviewer"] = reviewer
    evidence["checked_at"] = checked_at
    evidence["source"] = source
    updated = True
if updated:
    data["status"] = "draft"
tmp = path.with_name(f".{path.name}.tmp-{os.getpid()}")
with tmp.open("w", encoding="utf-8") as handle:
    json.dump(data, handle, ensure_ascii=False, indent=2)
    handle.write("\n")
    handle.flush()
    os.fsync(handle.fileno())
os.replace(tmp, path)
PY
}

category_rows() {
  local category="$1" keyword="$2"
  "$PYTHON" - "$BENCHMARK_FILE" "$REVIEW_GRID_FILE" "$category" "$keyword" <<'PY'
import json
import math
import sys
from urllib.parse import urlencode

benchmark_path, grid_path, category, keyword = sys.argv[1:]
benchmark = json.load(open(benchmark_path, encoding="utf-8"))
grid = json.load(open(grid_path, encoding="utf-8"))
labels = {item["grid_id"]: item for item in benchmark.get("labels", [])}

def bd09_to_gcj02(lng, lat):
    x_pi = math.pi * 3000.0 / 180.0
    x = lng - 0.0065
    y = lat - 0.006
    z = math.sqrt(x * x + y * y) - 0.00002 * math.sin(y * x_pi)
    theta = math.atan2(y, x) - 0.000003 * math.cos(x * x_pi)
    return z * math.cos(theta), z * math.sin(theta)

features = sorted(
    (
        feature
        for feature in grid.get("features", [])
        if feature.get("properties", {}).get("category") == category
    ),
    key=lambda feature: feature.get("properties", {}).get("grid_id", ""),
)
for feature in features:
    grid_id = feature["properties"]["grid_id"]
    ring = feature["geometry"]["coordinates"][0]
    points = ring[:-1] if len(ring) > 1 and ring[0] == ring[-1] else ring
    bd_lng = sum(point[0] for point in points) / len(points)
    bd_lat = sum(point[1] for point in points) / len(points)
    gcj_lng, gcj_lat = bd09_to_gcj02(bd_lng, bd_lat)
    query = urlencode(
        {
            "keyword": keyword,
            "center": f"{gcj_lng:.6f},{gcj_lat:.6f}",
            "city": "广州",
            "src": "life-circle-assistant",
            "coordinate": "gaode",
            "callnative": "0",
        }
    )
    label = labels.get(grid_id, {})
    evidence = label.get("evidence", {})
    completed = bool(
        label.get("expected_kind") in {"normal", "sparse", "critical"}
        and evidence.get("source")
        and evidence.get("checked_at")
        and evidence.get("reviewer")
        and evidence.get("notes")
    )
    print(
        "\t".join(
            (
                grid_id,
                f"{gcj_lng:.6f}",
                f"{gcj_lat:.6f}",
                "https://uri.amap.com/search?" + query,
                "1" if completed else "0",
            )
        )
    )
PY
}

save_label() {
  local grid_id="$1" expected_kind="$2" notes="$3"
  "$PYTHON" - "$BENCHMARK_FILE" "$grid_id" "$expected_kind" "$EVIDENCE_SOURCE" "$CHECKED_AT" "$REVIEWER" "$notes" <<'PY'
import json
import os
import sys
from pathlib import Path

path = Path(sys.argv[1])
grid_id, expected_kind, source, checked_at, reviewer, notes = sys.argv[2:]
data = json.loads(path.read_text(encoding="utf-8"))
for label in data.get("labels", []):
    if label.get("grid_id") != grid_id:
        continue
    label["expected_kind"] = expected_kind
    label["evidence"] = {
        "source": source,
        "checked_at": checked_at,
        "reviewer": reviewer,
        "notes": notes,
    }
    break
else:
    raise SystemExit(f"未找到网格：{grid_id}")
data["status"] = "draft"
tmp = path.with_name(f".{path.name}.tmp-{os.getpid()}")
with tmp.open("w", encoding="utf-8") as handle:
    json.dump(data, handle, ensure_ascii=False, indent=2)
    handle.write("\n")
    handle.flush()
    os.fsync(handle.fileno())
os.replace(tmp, path)
PY
}

review_category() {
  local category="$1" category_label="$2" keyword="$3"
  local grid_id center_lng center_lat url completed choice expected_kind notes

  say "本阶段核查 $category_label 的 16 个网格，已完整填写的网格会自动跳过。"
  note "高德链接只是独立核查入口；请同时核对实际步行通道、围墙、铁路、厂区、河道和过街点。"
  printf '\n'

  while IFS=$'\t' read -r grid_id center_lng center_lat url completed; do
    if [[ "$completed" == "1" ]]; then
      say "✓ $grid_id 已完成，跳过"
      continue
    fi

    printf '\n  %s%s%s（高德坐标 %s, %s）\n' "$BOLD" "$grid_id" "$RESET" "$center_lng" "$center_lat"
    open_url "$url"
    step "核对 1 公里内是否有同类设施，以及最近有效步行路线是否不超过 15 分钟。"
    say "1=normal（两项都满足）  2=sparse（只满足一项）  3=critical（两项都不满足）  q=保存退出"
    while true; do
      printf '  %s请选择判定 [1/2/3/q]：%s ' "$BOLD" "$RESET"
      read -r choice || choice="q"
      case "$choice" in
        1) expected_kind="normal"; break ;;
        2) expected_kind="sparse"; break ;;
        3) expected_kind="critical"; break ;;
        q|Q)
          say "已保留之前完成的核查。下次运行将从未完成网格继续。"
          exit 0
          ;;
        *) warn "请输入 1、2、3 或 q。" ;;
      esac
    done

    while true; do
      printf '  %s核查备注（最近设施、步行时间和道路条件；q 退出）：%s ' "$BOLD" "$RESET"
      read -r notes || notes="q"
      if [[ "$notes" == "q" || "$notes" == "Q" ]]; then
        say "当前网格未保存，之前完成的核查已保留。"
        exit 0
      fi
      [[ -n "$notes" ]] && break
      warn "核查备注不能为空。"
    done

    save_label "$grid_id" "$expected_kind" "$notes"
    printf '  %s✓ 已保存%s %s → %s\n' "$GREEN" "$RESET" "$grid_id" "$expected_kind"
  done < <(category_rows "$category" "$keyword")
}

validation_summary() {
  "$PYTHON" - "$BENCHMARK_FILE" <<'PY'
import json
import sys

data = json.load(open(sys.argv[1], encoding="utf-8"))
labels = data.get("labels", [])
valid_kinds = {"normal", "sparse", "critical"}
incomplete = []
for label in labels:
    evidence = label.get("evidence", {})
    if label.get("expected_kind") not in valid_kinds or any(
        not evidence.get(field) for field in ("source", "checked_at", "reviewer", "notes")
    ):
        incomplete.append(label.get("grid_id", "<unknown>"))
print(f"{len(labels) - len(incomplete)}\t{len(labels)}\t{','.join(incomplete[:8])}")
PY
}

mark_verified() {
  "$PYTHON" - "$BENCHMARK_FILE" <<'PY'
import json
import os
import sys
from pathlib import Path

path = Path(sys.argv[1])
data = json.loads(path.read_text(encoding="utf-8"))
valid_kinds = {"normal", "sparse", "critical"}
for label in data.get("labels", []):
    evidence = label.get("evidence", {})
    if label.get("expected_kind") not in valid_kinds or any(
        not evidence.get(field) for field in ("source", "checked_at", "reviewer", "notes")
    ):
        raise SystemExit(f"网格 {label.get('grid_id')} 标注或证据不完整")
data["status"] = "verified"
tmp = path.with_name(f".{path.name}.tmp-{os.getpid()}")
with tmp.open("w", encoding="utf-8") as handle:
    json.dump(data, handle, ensure_ascii=False, indent=2)
    handle.write("\n")
    handle.flush()
    os.fsync(handle.fileno())
os.replace(tmp, path)
PY
}

print_metrics() {
  "$PYTHON" - "$RESULT_JSON" <<'PY'
import json
import sys

result = json.load(open(sys.argv[1], encoding="utf-8"))
metrics = result["metrics"]
completeness = result["completeness"]

def percent(value):
    return "—" if value is None else f"{value * 100:.1f}%"

print(f"  准确率：{percent(metrics['accuracy'])}")
print(f"  宏平均召回率：{percent(metrics['macro_recall'])}")
print(f"  宏平均 F1：{percent(metrics['macro_f1'])}")
print(
    "  标注完成度："
    f"{completeness['reviewed_label_count']} / {completeness['expected_label_count']} "
    f"（{percent(completeness['review_completion_rate'])}）"
)
PY
}

require_file "$REPORT_FILE"
require_file "$BENCHMARK_FILE"
require_file "$REVIEW_GRID_FILE"

banner "红山街道全网格人工核查"

stage "设置核查信息"
