say "核查信息已保存到未完成标注。"

stage "菜市场（16 格）"
review_category "market" "菜市场" "菜市场"

stage "药店（16 格）"
review_category "pharmacy" "药店" "药店"

stage "小学（16 格）"
review_category "school" "小学" "小学"

stage "医疗服务（16 格）"
review_category "medical" "医疗服务" "医疗服务"

stage "校验并生成评估结果"
IFS=$'\t' read -r completed_count total_count missing_preview < <(validation_summary)
say "已完整核查 $completed_count / $total_count 项。"
if [[ "$completed_count" != "$total_count" ]]; then
  warn "仍有未完成项：${missing_preview:-详见基准 JSON}。基准保持 draft，不生成正式评估。"
  exit 0
fi

if ! confirm "确认 64 项均已依据独立证据完成，将基准标记为 verified 并生成评估？"; then
  say "已取消发布；所有标注已保存，基准状态不变。"
  exit 0
fi

mark_verified
mkdir -p "$(dirname "$RESULT_JSON")"
"$PYTHON" "$APP_ROOT/backend/scripts/evaluate_benchmark.py" evaluate \
  --report "$REPORT_FILE" \
  --benchmark "$BENCHMARK_FILE" \
  --json-output "$RESULT_JSON" \
  --markdown-output "$RESULT_MD"
printf '\n'
print_metrics
note "JSON 结果：$RESULT_JSON"
note "Markdown 报告：$RESULT_MD"

finish
